PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry scan_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 rows,
    .param .u32 cols
)
{
    // ------------------------------
    // Registers
    // ------------------------------
    .reg .u64   %in_ptr, %out_ptr;
    .reg .u64   %row_base_in, %row_base_out;
    .reg .u64   %addr;
    .reg .u32   %row_idx, %cols, %i;
    .reg .u16   %val_h;
    .reg .f32   %val_f, %sum_f;
    .reg .pred  %p;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64 %in_ptr,   [in_ptr];
    ld.param.u64 %out_ptr,  [out_ptr];
    ld.param.u32 %rows,     [rows];   // not used directly
    ld.param.u32 %cols,     [cols];

    // Convert generic pointers to global address space
    cvta.to.global.u64 %in_ptr,  %in_ptr;
    cvta.to.global.u64 %out_ptr, %out_ptr;

    // ------------------------------
    // Compute row offset (blockIdx.x)
    // ------------------------------
    mov.u32 %row_idx, %ctaid.x;                     // blockIdx.x
    mul.wide.u32 %addr, %row_idx, %cols;            // %addr = row_idx * cols
    mul.wide.u32 %addr, %addr, 2;                   // *2 because each fp16 is 2 bytes
    add.u64 %row_base_in, %in_ptr, %addr;           // base address for this row (input)
    add.u64 %row_base_out, %out_ptr, %addr;         // base address for this row (output)

    // ------------------------------
    // Prefix‑sum loop (scalar implementation)
    // ------------------------------
    mov.f32 %sum_f, 0f00000000;                     // sum = 0.0f

    mov.u32 %i, 0;
Loop:
    setp.ge.u32 %p, %i, %cols;
    @%p bra EndLoop;

    // address = row_base + i*2
    mul.wide.u32 %addr, %i, 2;
    add.u64 %addr, %row_base_in, %addr;
    ld.global.u16 %val_h, [%addr];

    // convert half -> float
    cvt.rn.f32.f16 %val_f, %val_h;

    // accumulate
    add.f32 %sum_f, %sum_f, %val_f;

    // convert back to half
    cvt.rn.f16.f32 %val_h, %sum_f;

    // store result
    mul.wide.u32 %addr, %i, 2;
    add.u64 %addr, %row_base_out, %addr;
    st.global.u16 [%addr], %val_h;

    // i = i + 1
    add.u32 %i, %i, 1;
    bra Loop;
EndLoop:

    ret;
}
'''

